import sys, numpy as np, json
sys.path.insert(0,'/opt/tools'); from rcb_client import Robot
r=Robot(); o=r.get_obs(depth=True)
img=o.last['ego']; d=o.last_depth['ego']; cam=o.meta['cameras']['ego']; E=np.array(cam['extrinsic_cv']); K=np.array(cam['intrinsic_cv']); inv=np.linalg.inv(E[:,:3]);
def world(u,v):
 z=d[v,u]; p=np.linalg.inv(K)@np.array([u,v,1.])*z; return (inv@(p-E[:,3])).tolist(), float(z)
print('shape',img.shape,'intr',K,'E',E,'depth valid',np.quantile(d[d>0],[0,.1,.5,.9,1]))
# pixels samples
for uv in [(295,285),(290,270),(420,300),(416,298),(380,260),(440,260),(420,180),(200,350),(300,320),(400,330),(350,330)]: print(uv,img[uv[1],uv[0]].tolist(),world(*uv))
# find exact green and orange masks
R,G,B=[img[:,:,i].astype(int) for i in range(3)]
for name,mask in [('green',(G>110)&(G>R*1.25)&(G>B*1.15)),('orange',(R>90)&(G>45)&(R>G*1.35)&(G>B*1.2)),('yellow',(R>130)&(G>110)&(B<100)&(R> B*1.5))]:
 ys,xs=np.where(mask); print(name,'n',len(xs),'bbox', (int(xs.min()),int(ys.min()),int(xs.max()),int(ys.max())) if len(xs) else None,'centroid',(float(xs.mean()),float(ys.mean())) if len(xs) else None)
 if len(xs):
  for u,v in [(int(xs.mean()),int(ys.mean())),(int(xs[len(xs)//2]),int(ys[len(xs)//2]))]: print(' sample',u,v,img[v,u],world(u,v))
# z world surface sample grid visible table
for uv in [(300,350),(500,350),(200,250),(600,300),(350,350),(450,400)]: print('table',uv,world(*uv))
